// A test that is laid over pkg/config of LiveKit's server at the pin and writes down what
// the original holds for a configuration: one line per value, `path=value`, the path made
// of the names in YAML. `test_default_config_equals_the_original` and
// the tests at the end of config_test.rs hold the port against what it wrote (go-default.txt
// for no file, go-sample.txt, go-edge.txt and go-errors.txt for config-sample-uncommented.yaml,
// config-edge.yaml and config-errors.yaml). To write those again, from the repository's root:
//
//	d=$PWD/crates/musivum/src/config/testdata
//	echo "{\"Replace\": {\"$PWD/reference/livekit/pkg/config/musivum_dump_test.go\": \"$d/dump_test.go\"}}" > target/overlay.json
//	MUSIVUM_OUT=$d/go-default.txt scripts/go-reference-test.sh -overlay $PWD/target/overlay.json -count=1 -run TestMusivumDump ./pkg/config
//	MUSIVUM_CONFIG=$d/config-sample-uncommented.yaml MUSIVUM_OUT=$d/go-sample.txt scripts/go-reference-test.sh -overlay $PWD/target/overlay.json -count=1 -run TestMusivumDump ./pkg/config
//
// and the same for the other two. A configuration the original does not take is written down
// as its error.
//
// The parts of the configuration that musivum takes from a file and does not read are left
// out. So are the addresses of the node when the original finds them itself: they are
// those of the machine the test runs on.
package config

import (
	"fmt"
	"os"
	"reflect"
	"sort"
	"strconv"
	"strings"
	"testing"

	"github.com/stretchr/testify/require"

	"github.com/livekit/mediatransportutil/pkg/rtcconfig"
)

var musivumIgnored = map[string]bool{
	"debug_handler":            true,
	"webtransport":             true,
	"redis":                    true,
	"ingress":                  true,
	"sip":                      true,
	"node_selector":            true,
	"signal_relay":             true,
	"psrpc":                    true,
	"agents":                   true,
	"trace":                    true,
	"node_stats":               true,
	"room.room_configurations": true,
}

func TestMusivumDump(t *testing.T) {
	out := os.Getenv("MUSIVUM_OUT")
	if out == "" {
		t.Skip("MUSIVUM_OUT is not set")
	}
	content := ""
	if in := os.Getenv("MUSIVUM_CONFIG"); in != "" {
		b, err := os.ReadFile(in)
		require.NoError(t, err)
		content = string(b)
	}

	conf, err := NewConfig(content, true, nil, nil)
	if err != nil {
		// what the original says to a configuration it does not take
		require.NoError(t, os.WriteFile(out, []byte("error="+err.Error()+"\n"), 0o644))
		return
	}

	lines := []string{fmt.Sprintf("rtc.node_ip_auto_generated=%t", conf.RTC.NodeIPAutoGenerated)}
	if conf.RTC.NodeIPAutoGenerated {
		conf.RTC.NodeIP = rtcconfig.NodeIP{}
	}
	musivumDump(t, reflect.ValueOf(conf).Elem(), "", &lines)
	sort.Strings(lines)
	require.NoError(t, os.WriteFile(out, []byte(strings.Join(lines, "\n")+"\n"), 0o644))
}

func musivumDump(t *testing.T, v reflect.Value, path string, lines *[]string) {
	if musivumIgnored[path] {
		return
	}
	add := func(format string, args ...any) {
		*lines = append(*lines, path+fmt.Sprintf(format, args...))
	}
	switch v.Kind() {
	case reflect.Ptr:
		if v.IsNil() {
			add("=nil")
			return
		}
		musivumDump(t, v.Elem(), path, lines)
	case reflect.Struct:
		for i := 0; i < v.NumField(); i++ {
			f := v.Type().Field(i)
			if !f.IsExported() {
				continue
			}
			parts := strings.Split(f.Tag.Get("yaml"), ",")
			if parts[0] == "-" {
				continue
			}
			p := path
			if len(parts) < 2 || parts[1] != "inline" {
				name := parts[0]
				if name == "" {
					name = strings.ToLower(f.Name)
				}
				if p != "" {
					p += "."
				}
				p += name
			}
			musivumDump(t, v.Field(i), p, lines)
		}
	case reflect.Slice:
		add(".len=%d", v.Len())
		for i := 0; i < v.Len(); i++ {
			musivumDump(t, v.Index(i), fmt.Sprintf("%s[%d]", path, i), lines)
		}
	case reflect.Map:
		add(".len=%d", v.Len())
		for _, k := range v.MapKeys() {
			musivumDump(t, v.MapIndex(k), fmt.Sprintf("%s{%v}", path, k.Interface()), lines)
		}
	case reflect.Bool:
		add("=%t", v.Bool())
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
		add("=%d", v.Int())
	case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
		add("=%d", v.Uint())
	case reflect.Float32:
		add("=%s", strconv.FormatFloat(v.Float(), 'f', -1, 32))
	case reflect.Float64:
		add("=%s", strconv.FormatFloat(v.Float(), 'f', -1, 64))
	case reflect.String:
		add("=%q", v.String())
	default:
		t.Fatalf("%s: a %s is not written down", path, v.Kind())
	}
}
